import { Fn, vec2, vec3, vec4, uv, texture, mix, smoothstep, float, uniform } from 'three/tsl';
import gsap from 'gsap';

const INK = new THREE.Color('#16161d');
const PAPER = new THREE.Color('#e8ecf2');
const ACCENT = new THREE.Color('#ff2a38');
const SURFACE = new THREE.Color('#0b0b10');

export default function createNode(config, ctx) {
  const {
    position = [0, 3, 0],
    rotation = [0, 0, 0],
    scale = [1, 1, 1],
  } = config.scenePlacement || {};

  const {
    assets = {},
    atlasRegion = { atlas: 0, x: 0, y: 0, width: 512, height: 320 },
    textContent = [],
  } = config;

  // Load grain texture (cached)
  const grainTexture = ctx.textureLoader(assets.imageUrl);
  grainTexture.colorSpace = THREE.SRGBColorSpace;
  grainTexture.wrapS = THREE.RepeatWrapping;
  grainTexture.wrapT = THREE.RepeatWrapping;

  // Ensure text rendered into font atlas
  const textItem = textContent[0] || { value: 'Features', font: 'Lora', weight: 400, size: 96 };
  const atlasInfo = ctx.fontAtlas.getAtlas(atlasRegion.atlas);
  const atlasTexture = atlasInfo.texture;
  const atlasW = atlasInfo.width;
  const atlasH = atlasInfo.height;

  ctx.fontAtlas.ensureText({
    text: textItem.value,
    font: textItem.font || 'Lora',
    weight: textItem.weight || 400,
    size: textItem.size || 96,
    atlasIndex: atlasRegion.atlas,
    region: { x: atlasRegion.x, y: atlasRegion.y, width: atlasRegion.width, height: atlasRegion.height },
  });

