  const u0 = atlasRegion.x / atlasW;
  const u1 = (atlasRegion.x + atlasRegion.width) / atlasW;
  const v1 = 1.0 - atlasRegion.y / atlasH;
  const v0 = 1.0 - (atlasRegion.y + atlasRegion.height) / atlasH;

  // Plane geometry sized to atlas region aspect ratio
  const aspect = atlasRegion.width / atlasRegion.height; // 1.6
  const headlineHeight = 0.34; // scene units from design tokens (headline scale)
  const planeW = headlineHeight * aspect;
  const planeH = headlineHeight;
  const geometry = new THREE.PlaneGeometry(planeW, planeH);

  // Remap UVs to atlas region
  const uvAttr = geometry.attributes.uv;
  // PlaneGeometry vertex order: TL(0,1), TR(1,1), BL(0,0), BR(1,0)
  uvAttr.setXY(0, u0, v1);
  uvAttr.setXY(1, u1, v1);
  uvAttr.setXY(2, u0, v0);
  uvAttr.setXY(3, u1, v0);
  uvAttr.needsUpdate = true;

  // TSL uniforms for colors
  const uInk = uniform(INK);
  const uPaper = uniform(PAPER);
  const uAccent = uniform(ACCENT);
  const uSurface = uniform(SURFACE);
  const uGrainTexture = uniform(grainTexture);
  const uAtlasTexture = uniform(atlasTexture);
  const uGrainScale = uniform(6.0);
  const uGrainStrength = uniform(0.06);

  // Fragment via TSL Fn
  const fragmentFn = Fn(() => {
    const vUv = uv();

    // Atlas sampling for text (using remapped UVs already set on geometry,
    // so uv() directly maps to atlas region)
    const textSample = texture(uAtlasTexture, vUv);
    const textAlpha = textSample.a;
    const textRgb = textSample.rgb;

