    const gradT = vUv.y.oneMinus();
    const baseColor = mix(uSurface, uInk, smoothstep(0.0, 1.0, gradT));

    // Thin accent line near the baseline (engineered detail, not pastel)
    const accentBand = smoothstep(float(0.04), float(0.0), vUv.y.sub(0.12).abs());
    const withAccent = mix(baseColor, uAccent, accentBand.mul(0.5));

    // Subtle grain modulation
