    const grain = texture(uGrainTexture, grainUv).r;
    const grainMod = grain.sub(0.5).mul(uGrainStrength);
    const grainedColor = withAccent.add(vec3(grainMod, grainMod, grainMod));

    // Composite: text (paper) over grained gradient background
    // Use atlas alpha for text mask; textRgb for color, fallback to paper
    const textColor = mix(uPaper, textRgb, float(0.3));
    const finalColor = mix(grainedColor, textColor, textAlpha);

    // Edge fade for clean sprite edges (anti-aliased frame)
    const edge = vUv.x.smoothstep(float(0.0), float(0.02))
      .mul(vUv.x.oneMinus().smoothstep(float(0.0), float(0.02)))
      .mul(vUv.y.smoothstep(float(0.0), float(0.02)))
      .mul(vUv.y.oneMinus().smoothstep(float(0.0), float(0.02)));
    const alpha = float(1.0); // solid sprite, no transparency needed for title plate

    return vec4(finalColor, alpha);
  });

  const material = new THREE.MeshBasicNodeMaterial({
    transparent: false,
    side: THREE.DoubleSide,
    depthWrite: true,
  });
