    material.dispose();
    uInk.dispose?.();
    uPaper.dispose?.();
    uAccent.dispose?.();
    uSurface.dispose?.();
    uGrainTexture.dispose?.();
    uAtlasTexture.dispose?.();
    uGrainScale.dispose?.();
    uGrainStrength.dispose?.();
    mesh.onBeforeRender = null;
  };

  return mesh;
}
